    const { pluginRoot: mirrorRoot, resolvedSha } =
      await fetchCtx.seam.materializeOrRefreshPluginMirror({
        locations,
        cloneUrl,
        ...(gitSource.ref !== undefined && { ref: gitSource.ref }),
        ...(authBundle !== undefined && { auth: authBundle }),
      });
